package proxy

import (
	"encoding/json"
	"fmt"
	"os"
	"strings"

	"github.com/ollama/ollama/internal/modelref"
	modelpkg "github.com/ollama/ollama/types/model"
)

// ClaudeDesktopRoutingCatalogFilename is generated by Claude setup in ~/.ollama.
// It contains routing metadata, never credentials or cached access decisions.
// Cloud rows require an explicit cloud model and a known required_plan value;
// setup writes "free" when verified metadata has no plan restriction.
const ClaudeDesktopRoutingCatalogFilename = "claude-desktop-routing.json"

func loadClaudeDesktopRoutingCatalog(path string) ([]ClaudeDesktopModel, error) {
	if path == "" {
		return nil, nil
	}
	data, err := os.ReadFile(path)
	if os.IsNotExist(err) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	var catalog *struct {
		Models []struct {
			Route          string `json:"route"`
			Model          string `json:"model"`
			RequiredPlan   string `json:"required_plan,omitempty"`
			MaxTokens      int    `json:"max_tokens,omitempty"`
			SupportsVision bool   `json:"supports_vision,omitempty"`
		} `json:"models"`
	}
	if err := json.Unmarshal(data, &catalog); err != nil {
		return nil, err
	}
	if catalog == nil {
		return nil, fmt.Errorf("Claude routing catalog must be an object")
	}
	byRoute := make(map[string]ClaudeDesktopModel, len(catalog.Models))
	for _, entry := range catalog.Models {
		ref, err := modelref.ParseRef(entry.Model)
		if !isClaudeDesktopRouteID(entry.Route) || !validClaudeDesktopModelName(entry.Model) || err != nil || !modelpkg.ParseName(ref.Base).IsValid() {
			return nil, fmt.Errorf("invalid Claude route %q or model %q", entry.Route, entry.Model)
		}
		if _, duplicate := byRoute[entry.Route]; duplicate {
			return nil, fmt.Errorf("duplicate Claude route %q", entry.Route)
		}
		model := newClaudeDesktopModel(strings.TrimSpace(entry.Model), "", strings.TrimSpace(entry.RequiredPlan), entry.MaxTokens)
		if model.OllamaModel != strings.TrimSpace(entry.Model) {
			return nil, fmt.Errorf("Claude model %q must use an explicit cloud route", entry.Model)
		}
		if model.Cloud && model.RequiredPlan == "" {
			return nil, fmt.Errorf("Claude model %q has no verified plan metadata", entry.Model)
		}
		model.gateway.SupportsVision = entry.SupportsVision
		byRoute[entry.Route] = model
	}
	models := make([]ClaudeDesktopModel, 0, len(byRoute))
	for _, slot := range claudeDesktopModelSlots {
		if model, ok := byRoute[slot.id]; ok {
			model.assignClaudeDesktopSlot(slot)
			models = append(models, model)
		}
	}
	return models, nil
}
